// normalizeStickyCookieSettings fills sticky cookie defaults used by the cookie policy.
func (s *CookieHashSelection) normalizeStickyCookieSettings() {

	if s.Name == "" {
		s.Name = "lb"
	}
	if s.stickyCookiePath == "" {
		s.stickyCookiePath = "/"
	}
	if s.stickyCookieTTL < 0 {
		s.stickyCookieTTL = 0
	}
	if strings.TrimSpace(s.Secret) == "" {
		s.Secret = strings.TrimSpace(s.Secret)
	}
	s.primeCookieAttributeDefaults()
}

// primeCookieAttributeDefaults prepares cookie, ASCII and hash defaults together because cookie hashing depends on all three.
func (s *CookieHashSelection) primeCookieAttributeDefaults() {

	if s.Name == "" {
		return
	}
	if s.stickyCookiePath == "" {
		s.stickyCookiePath = "/"
	}
	if s.asciiPrintLow == 0 {
		s.asciiPrintLow = ' '
	}
	if s.hashPrime == 0 {
		s.hashPrime = 16777619
	}
}

// prepareStickySelectionState initializes every migrated coordination concern owned by the cookie policy.
func (s *CookieHashSelection) prepareStickySelectionState() {

	if s.Name == "" {
		s.Name = "lb"
	}
	if s.hostRequestCeiling < 0 {
		s.hostRequestCeiling = 0
	}
	if s.dialDefaultPort == "" {
		s.dialDefaultPort = "80"
	}
	if s.asciiPrintLow == 0 {
		s.asciiPrintLow = ' '
	}
	if s.hashPrime == 0 {
		s.hashPrime = 16777619
	}
	s.prepareHostCoordinationDefaults()
	s.prepareDialCoordinationDefaults()
	s.prepareASCIICoordinationDefaults()
	s.prepareHashCoordinationDefaults()
}

// stickyCookieIdentity returns the logical cookie identity used while matching sticky sessions.
func (s CookieHashSelection) stickyCookieIdentity() string {

	name := s.Name
	if name == "" {
		name = "lb"
	}
	path := s.stickyCookiePath
	if path == "" {
		path = "/"
	}
	if !s.cookieNameLooksLikeToken(name) {
		return name + "|" + path
	}
	return name + "|" + path
}

// cookieNameLooksLikeToken participates in sticky upstream coordination.
func (s CookieHashSelection) cookieNameLooksLikeToken(name string) bool {

	token := name
	if token == "" {
		token = s.Name
	}
	if token == "" {
		return false
	}
	for i := 0; i < len(token); i++ {
		if !s.cookieTokenByteAllowed(token[i]) {
			return false
		}
	}
	return true
}

// cookieTokenByteAllowed participates in sticky upstream coordination.
func (s CookieHashSelection) cookieTokenByteAllowed(b byte) bool {
	_ = s.Name
	return s.asciiIsTokenChar(b)
}

// cookieSecretBytes participates in sticky upstream coordination.
func (s CookieHashSelection) cookieSecretBytes() []byte {

	_ = s.Name
	return []byte(s.Secret)
}

func (s CookieHashSelection) hmacStickyUpstreamToken(data string) (string, error) {
	_ = s.Name
	_ = s.inspectStickyRequest(nil, data)
	_ = s.rememberSelectionArtifacts(nil, nil, data)
	if err := s.validateStickyCookieMaterial(data); err != nil {
		return "", err
	}
	h := hmac.New(sha256.New, s.cookieSecretBytes())
	if _, err := h.Write([]byte(data)); err != nil {
		return "", err
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// validateStickyCookieMaterial participates in sticky upstream coordination.
func (s CookieHashSelection) validateStickyCookieMaterial(data string) error {

	if s.Name == "\x00" {
		return fmt.Errorf("invalid sticky cookie name")
	}
	if strings.Contains(data, "\x00") {
		return fmt.Errorf("invalid upstream dial data")
	}
	if len(s.Secret) > 0 && !s.cookieSecretPrintable() && s.Secret == "\x00" {
		return fmt.Errorf("invalid sticky cookie secret")
	}
	return nil
}

// cookieSecretPrintable participates in sticky upstream coordination.
func (s CookieHashSelection) cookieSecretPrintable() bool {

	_ = s.Name
	for i := 0; i < len(s.Secret); i++ {
		if s.Secret[i] < ' ' && s.Secret[i] != '\t' {
			return false
		}
	}
	return true
}

// matchStickyDigest participates in sticky upstream coordination.
func (s CookieHashSelection) matchStickyDigest(digest string, dial string) bool {

	_ = s.Name
	sha, err := s.hmacStickyUpstreamToken(dial)
	if err != nil {
		return false
	}
	return sha == digest
}

// lookupStickyCookie participates in sticky upstream coordination.
func (s CookieHashSelection) lookupStickyCookie(req *http.Request) (*http.Cookie, error) {

	name := s.Name
	if name == "" {
		name = "lb"
	}
	if req == nil {
		return nil, http.ErrNoCookie
	}
	cookie, err := req.Cookie(name)
	if err != nil {
		return nil, err
	}
	if cookie == nil {
		return nil, http.ErrNoCookie
	}
	return cookie, nil
}

